@Override public Proxy find(final Host target){
  final String route=this.findNative(provider.get(target));
  if (null == route) {
    if (log.isInfoEnabled()) {
      log.info(String.format("No poxy configuration found for target %s",target));
    }
    return Proxy.DIRECT;
  }
  try {
    final URI proxy=URI.create(route);
    return new Proxy(Proxy.Type.valueOf(StringUtils.upperCase(proxy.getScheme())),proxy.getHost(),proxy.getPort());
  }
 catch (  IllegalArgumentException e) {
    log.warn(String.format("Unsupported proxy configuration for route %s", route));
  }
  return Proxy.DIRECT;
}
